B="BK-741"
C=[
("S11",2928,3055,"أنواع الكسور تحكي شيئاً عن طريقة الإصابة","تختلف الكسور في شكلها بحسب اتجاه القوة وسرعتها وحجم السطح الذي لامس العظم. قراءة الكسر تعطي فكرة عامة عن نوع الجسم المسبب وجهة القوة لا أكثر.","يكتب المحقق ما يلاحظه عن شكل الإصابة بوصف محايد ثم يسأل الطبيب عن الأدوات المتوافقة معها، بدل أن يقفز إلى أداة بعينها.","شكل الكسر لا يحدد وحده أداة واحدة؛ أدوات مختلفة قد تترك آثاراً متقاربة، وحالة العظم والعمر تغيّر الصورة.","","16-18","conceptual","scene_documentation",["KO-FC-04-022","KO-RS-06-004"],["كسر","اتجاه القوة"]),
("S11",2928,3055,"الإصابة الظاهرة قد لا تعكس حجم الأذى الداخلي","قد يبدو الجلد سليماً بينما يوجد أذى أعمق، وقد يحدث العكس. لذلك لا يُحكم على خطورة الواقعة من منظر السطح فقط.","يوثّق المحقق ما يراه ويترك تقدير الأذى الداخلي للفحص الطبي، ولا يكتب استنتاجاً عن الخطورة في محضر المعاينة.","التقدير الطبي يحتاج فحصاً مباشراً وقد يتغير بمرور الوقت.","الجلد السليم يعني أنه لا أذى.","all","safe","reporting",["KO-RS-06-004","KO-FC-04-022"],["أذى داخلي","معاينة"]),
("S11",2928,3055,"الشخص المصاب الذي يُعثر عليه: أسئلة قبل الاستنتاج","عند العثور على شخص مصاب أو متوفٍّ توضع عدة تفسيرات ممكنة: حادث، اعتداء، سقوط، أو فعل ذاتي، ويُبحث عمّا يميّز بينها في المكان والجسد والظروف.","يكتب المحقق جدولاً قصيراً: ما الذي يدعم كل تفسير وما الذي يضعفه، ثم يحدد المعاينة التي ستفرّق بينها.","وجود تفسير أول مريح لا يعني صحته؛ قد تتوافق عدة تفسيرات مع المعطيات المتاحة.","","16-18","conceptual","witness_reliability",["KO-RS-05-002","KO-RS-05-003","KO-RS-06-006"],["فرضيات متنافسة","اختبار مميِّز"]),
("S11",2928,3055,"الجروح المفتعلة قد تقع في أماكن يسهل بلوغها","يذكر الكتاب أن الإصابات التي يدّعي صاحبها أنها من غيره قد تظهر في مواضع يصل إليها هو بيده بسهولة. موضع الإصابة قرينة تُضاف إلى غيرها ولا تُعدّ دليلاً بذاتها.","عند تضارب الرواية مع شكل الإصابة، يُسجَّل التضارب ويُطلب فحص طبي مستقل وتُقارن الرواية بمسرح الواقعة.","موضع الإصابة وحده لا يثبت الافتعال، فالمعتدى عليه الحقيقي قد يُصاب في أي مكان.","كل إصابة يسهل بلوغها مفتعلة.","16-18","conceptual","witness_reliability",["KO-RS-05-014","KO-RS-05-009"],["مطابقة الرواية للأثر"]),
("S12",3056,3250,"الاستعراف: معرفة هوية مجهول خطوة قبل أي تحقيق آخر","الاستعراف هو الوصول إلى هوية شخص أو جثة مجهولة بمقارنة صفات مسجّلة بصفات مأخوذة من البحث. تنقسم الوسائل إلى صفات عامة قابلة للتكرار وصفات مميِّزة نادرة.","يبدأ المحقق بجمع الصفات المميِّزة وتوثيقها بالصور والوصف، ثم يعرضها على الجهات التي تتلقى بلاغات المفقودين.","الصفة العامة كالطول واللون لا تثبت هوية؛ تضيّق الاحتمالات فقط.","","16-18","safe","scene_documentation",["KO-RS-05-001","KO-FC-04-026"],["استعراف","صفة مميِّزة"]),
("S12",3056,3250,"قضية تعرّف على مجهول من خلال التعميم على بلاغات المفقودين","تعرض صفحات الكتاب واقعة تم فيها الوصول إلى اسم شخص مجهول بمقارنة أوصافه بما ورد من بلاغات اختفاء ومن تعميمات على الجهات المحلية. الفكرة أن الجهد المنظم في جمع البلاغات يسبق الأدلة المخبرية.","في الألغاز: قبل البحث عن دليل معقد، اسأل من يفتقد هذا الشخص وأين تسجَّل البلاغات.","التطابق في الأوصاف لا يكفي؛ يلزم تأكيد بوسيلة مستقلة.","","all","safe","reporting",["KO-RS-05-004","KO-RS-05-005"],["بلاغ مفقود","تأكيد مستقل"]),
("S12",3056,3250,"قضية تتبّع جناة عبر سجلات الطريق وقوائم المشتبه بهم المعروفين","يعرض الكتاب واقعة تم فيها تضييق الدائرة بسجلات يومية للمرور وبمقارنة قوائم معروفة بالسرقة، ثم تثبيت الصلة بأدلة أخرى. تتجمع الخيوط الضعيفة عبر استقلال مصادرها.","في الألغاز: اجمع خيوطاً من مصادر لا تعتمد على بعضها ثم ابحث عن نقطة التقاؤها.","كون الشخص في قائمة سابقة لا يثبت تورطه الحالي؛ هو مجرد دافع للتحقق.","القائمة السابقة تعني الإدانة.","16-18","conceptual","witness_reliability",["KO-RS-05-004","KO-RS-06-010"],["استقلال الأدلة","نسبة الأساس"]),
("S12",3056,3250,"البصمة لا تتغير بالعمر لكن قد تتغير بالإصابة والحرفة","يصف الكتاب أن نمط خطوط الأصابع ثابت عادة، وأن الجروح العميقة والأمراض والمهن اليدوية قد تشوّه الأثر الملتقط. لذلك قد يظهر أثر مختلف لنفس الشخص في ظرفين.","عند مقارنة أثرين، يسأل الفاحص عن أحوال الجلد والحامل وطريقة الأخذ قبل أن يقرّر عدم التطابق.","التشوه لا يثبت التلاعب، والتلاعب لا يثبت بمجرد اختلاف الأثر.","","16-18","safe","lab_limits",["KO-FC-04-012"],["بصمة","تشوه"]),
("S12",3056,3250,"أين تُترك الآثار الدقيقة ومن أين تأتي؟","توجد آثار الأصابع في الأماكن التي لمسها الناس فعلاً: المقابض، الأسطح الملساء، الأدوات. وجود أثر لشخص في مكان له وصول مشروع إليه لا يعني شيئاً عن توقيت لمسه.","يفرّق المحقق بين أثر من له وصول معتاد وأثر في موضع لا يصل إليه إلا من فتحه، ويسأل عن توقيت الأثر.","الأثر يدل على اللمس لا على الزمن ولا على النية.","وجود بصمة المتهم يكفي لإدانته.","16-18","safe","lab_limits",["KO-FC-04-012","KO-FC-04-007","KO-RS-06-001"],["أثر لمس","قيمة تشخيصية"]),
("S12",3056,3250,"لا تلمس المسرح قبل أن يصل مختص الآثار","يؤكد الكتاب قاعدة العمل: من يصل أولاً يحافظ على الموضع ولا يمسح أو يحرّك ما قد يحمل أثراً. أي لمسة جديدة قد تُغطي القديمة أو تضيف أثراً غير مرتبط بالواقعة.","في الألغاز: أول من يصل إلى المكان يُسجَّل اسمه ووقته وما لمسه إن لزم.","الحفاظ التام ليس ممكناً دائماً (إسعاف، خطر)؛ المهم توثيق كل تدخل.","","all","safe","evidence_handling",["KO-FC-04-026","KO-FC-04B-002"],["حفظ المسرح","سلسلة الحيازة"]),
("S12",3056,3250,"الأثر المطبوع على سطح لين يُصوَّر في مكانه","يذكر الكتاب أن الآثار على الأسطح الطرية لا تُرفع بالطرق المعتادة وأن تصويرها في موضعها أفضل ما يُفعل أولاً. المبدأ العام: ثبّت الصورة قبل أن تجرّب أي معالجة قد تفسد الأثر.","التوثيق بالصور بمقياس يسبق التدخل، وهذه قاعدة تصلح لكل أنواع الآثار.","الصورة لا تغني عن الأثر الأصلي حين يمكن حفظه.","","13-15","safe","scene_documentation",["KO-FC-04-026"],["تصوير بمقياس","توثيق قبل المعالجة"]),
("S12",3056,3250,"المقارنة بين أثرين ليست عملية آلية بنعم أو لا","يعرض الكتاب معيار عدد نقاط التشابه المطلوبة ويصوّره كأنه حاسم. في المنهج الحديث تُقدَّم المقارنة كحكم خبير له نسبة خطأ ويُصاغ تقريره بلغة احتمالية متحفظة.","اقرأ تقرير المقارنة بحثاً عن: كم نقطة اعتُمدت؟ من راجع النتيجة؟ هل راجعها فاحص ثانٍ مستقل؟","لا يوجد عدد سحري مقبول عالمياً، والقول بأن الأثر لا يتكرر مطلقاً أقوى من الدليل.","كل بصمة فريدة ومقارنتها لا تخطئ أبداً.","16-18","conceptual","lab_limits",["KO-FC-04B-005","KO-FC-04-031","KO-RS-07B-001"],["مقارنة","لغة احتمالية"]),
("S12",3056,3250,"الصفات التي يمكن استنتاجها من الأثر تقريبية","يذكر الكتاب أن حجم الأثر وكثافة خطوطه قد يشيران إلى فئة عمرية وأن آثار الحرفة قد توحي بالمهنة. هذه الاستنتاجات تقريبية وتصلح فقط لتوجيه البحث.","استعمل التقدير لتحديد من تبدأ بسؤالهم، لا لتجاهل غيرهم.","التعميم على المهنة أو العمر خطر لأن الاستثناءات كثيرة.","من يده خشنة فهو عامل.","all","safe","reporting",["KO-RS-06-010","KO-RS-06-004"],["استنتاج تقريبي"]),
("S12",3056,3250,"تقدير الطول والجنس من الهياكل: نطاقات لا أرقام قاطعة","تعرض الصفحات طرقاً تقريبية لتقدير الطول من أبعاد الجسم أو العظام الطويلة ولتمييز الجنس من الحوض والجمجمة. النتائج نطاقات احتمالية تتغير بحسب الفئة السكانية.","يُطلب من مختص عظام قبل أن يُكتب أي رقم في ملف الاستعراف، ويُكتب النطاق لا الرقم الواحد.","المعادلات القديمة صُمّمت لفئات معينة وقد لا تصلح لغيرها.","","18+","conceptual","lab_limits",["KO-FC-04-021","KO-RS-07B-001"],["نطاق تقديري","عظام طويلة"]),
("S12",3056,3250,"تقدير الأصل أو الجنسية من الهيكل: تحذير من التعميم","يتضمن الكتاب وصفاً لتصنيف الأصول من ملامح العظام. هذا فرع قديم تستخدمه المراجع الحديثة بحذر شديد، ولا يصلح أساساً لأي حكم على شخص.","في المنصة: لا نستعمل هذا التصنيف أداةً في الألغاز؛ نذكر فقط أن الاعتماد على صفة واحدة خطأ منهجي.","التصنيفات الواردة قديمة وعامة ولا تُستعمل في قرارات.","الملامح تحدد الأصل بيقين.","18+","sensitive","lab_limits",["KO-RS-06-020","KO-RS-06-010"],["تعميم","تحيّز"]),
("S12",3056,3250,"وصف الملابس والمتعلقات جزء من الاستعراف","يوصي الكتاب بتوثيق لون الملابس ونوع القماش وعلاماتها وما في الجيوب وحفظها لعرضها على المعارف. هذه أدلة داعمة تستند إلى ذاكرة الآخرين ولذلك تحتاج توثيقاً دقيقاً.","سجّل وصف المتعلقات بالصور والكلمات قبل عرضها على أي شاهد، حتى لا يتأثر الشاهد بما تراه.","تعرُّف الأقارب على متعلق قد يتأثر بالرغبة والتوقع.","","all","safe","witness_reliability",["KO-RS-05-008","KO-FC-04-026"],["متعلقات","عرض الشاهد"]),
("S12",3056,3250,"الندبات والوشوم والعلامات الخلقية صفات شبه دائمة","هذه العلامات لا تزول إلا بتدخل جراحي أو كيميائي يترك أثراً. قدّر الكتاب أن الندبة تتغير في لونها وشكلها مع الزمن بما يعطي فكرة تقريبية عن عمرها.","صوّر العلامة وارسم موضعها بالنسبة لنقاط ثابتة في الجسم، ثم قارنها بسجلات طبية أو صور سابقة.","تقدير عمر الندبة بصرياً تقريبي جداً.","","16-18","safe","scene_documentation",["KO-FC-04-021","KO-FC-04-026"],["ندبة","علامة مميِّزة"]),
]
